export const ICONSCOUT_AVATAR_COUNT = PEOPLE_AVATAR_LABELS.length;
/** One undivided group: avatars are never sorted by identity. */
export const ICONSCOUT_AVATARS_PER_CATEGORY = ICONSCOUT_AVATAR_COUNT;
export const ICONSCOUT_CATEGORY_COUNT = 1;

export const ICONSCOUT_CATEGORY_LABELS = ['Avatars'] as const;

export const AVATAR_ASSET_BASE_PATH = '/avatars/people';
export const AVATAR_ASSET_EXTENSION = '.svg';
